import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/** That the person `personId` names `patronId`, another person on the sheet, as a patron. */
export type Patron = { personId: number; patronId: number };

/** The query key for the sheet's patrons; under sheetKey, so re-loading the sheet re-reads them. */
export const patronsKey = (sheet: string) => [...sheetKey(sheet), 'patrons'] as const;

/** Every person's patrons on the sheet. */
export function usePatrons() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: patronsKey(sheet),
    queryFn: () => getJson<Patron[]>(`/api/sheets/${encodeURIComponent(sheet)}/patrons`),
    enabled: !!sheet,
  });
}

/** The ids of the person's patrons. */
export const patronIdsOf = (patrons: Patron[], personId: number) =>
  patrons.filter((p) => p.personId === personId).map((p) => p.patronId);
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { claimsKey, useClaims } from './claims';
import type { Claim } from './claims';
import { useSelectedClaims } from './selection';
import { useOneAtATime } from '../../query/useOneAtATime';

// Settles every ticked claim, one after another in list order (people in their order, each one's
// claims newest first), as the signed-in user. Each goes through the claim's own settle action, so a
// clerk's settle above the clerk limit makes it PENDING and still counts as settled; one the server
// refuses is left as it is and counted as refused.
export function BulkSettle() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const [selected, , clear] = useSelectedClaims();
  const [result, setResult] = useState<{ settled: number; refused: number } | undefined>(undefined);
  const [busy, setBusy] = useState(false);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  if (!user || !sheet) return null;

  const run = async () => {
    setResult(undefined);
    setBusy(true);
    const ordered = people.flatMap((p) => claims.filter((c) => c.personId === p.id && selected.has(c.id)));
    let settled = 0;
    let refused = 0;
    try {
      for (const c of ordered) {
        try {
          await postJson<Claim>(
            `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/settle?user=${encodeURIComponent(user)}`,
            {},
          );
          settled++;
        } catch {
          refused++;
        }
      }
      // A ticked claim no longer listed (gone from the sheet) cannot be settled.
      refused += selected.size - ordered.length;
      clear();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    } finally {
      setBusy(false);
      setResult({ settled, refused });
    }
  };

  return (
    <p>
      <button type="button" data-testid="bulk-settle" disabled={busy} onClick={() => once(run)}>
        Settle selected claims
      </button>
      {result && (
        <>
          {' '}
          Settled <span data-testid="bulk-settled">{result.settled}</span>, refused{' '}
          <span data-testid="bulk-settle-refused">{result.refused}</span>
        </>
      )}
    </p>
  );
}
package net.officefloor.hq.app.patron;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class PatronRepository {

    private final JdbcTemplate jdbc;

    public PatronRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's people's patrons, by person and then in the order they were named. */
    public List<Patron> findAll(String sheetId) {
        return jdbc.query(
                "SELECT sheet_id, person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY person_id, patron_id",
                (rs, n) -> new Patron(rs.getString("sheet_id"), rs.getLong("person_id"), rs.getLong("patron_id")),
                sheetId);
    }

    /** Whether the person already names this patron. */
    public boolean exists(String sheetId, long personId, long patronId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person_patron WHERE sheet_id = ? AND person_id = ? AND patron_id = ?",
                Integer.class, sheetId, personId, patronId);
        return n != null && n > 0;
    }

    public void save(Patron patron) {
        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id) VALUES (?, ?, ?)", patron.sheetId(),
                patron.personId(), patron.patronId());
    }
}
