    onError: () => setError('The watch could not be changed.'),
  });

  return (
    <td>
      <span data-testid="person-watched">{watched ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="person-watch"
        disabled={toggle.isPending}
        onClick={() => {
          setError('');
          once(() => toggle.mutateAsync());
        }}
      >
        {watched ? 'Unwatch' : 'Watch'}
      </button>
    </td>
  );
}
